import sys
import math

def query(l, r, left_indices, right_indices):
    print(f"? {l} {r}")
    print(" ".join(map(str, left_indices)))
    print(" ".join(map(str, right_indices)))
    sys.stdout.flush()
    return int(input().strip())

def find_demagnetized_magnets(n):
    demagnetized = set()
    max_queries = n + math.floor(math.log2(n))
    queries_used = 0

    # Query pairs to identify demagnetized magnets
    for i in range(1, n+1):
        for j in range(i+1, n+1):
            if queries_used >= max_queries:
                break
            force = query(1, 1, [i], [j])
            if force == 0:
                demagnetized.add(i)
                demagnetized.add(j)
            queries_used += 1
        if queries_used >= max_queries:
            break

    return len(demagnetized), list(demagnetized)

t = int(input().strip())
for _ in range(t):
    n = int(input().strip())
    k, A = find_demagnetized_magnets(n)
    print(f"! {k} {' '.join(map(str, A))}")
